    double negative_slope);

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("fused_groupnorm_leakyrelu_sum", &fused_groupnorm_leakyrelu_sum_cuda,
          "Fused GroupNorm + LeakyReLU + x+x (CUDA)");
