CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

// Kernel specialized for channels_per_group == 16 (benchmark shape: hidden=8192, num_groups=512)
// Each warp (32 threads) handles 2 groups from the same row.
// Thread layout: threadIdx.x in [0,15] -> channel within group
//                threadIdx.x in [16,31] -> second group
// Grid: (batch_size, num_groups / 2) but we pack 2 groups per block for better occupancy.
// Actually: grid(num_groups * batch_size / groups_per_block), block(32)
// Simpler: one block per (row, group), blockDim.x = 32 but only 16 active threads per group.
// Best for group_size=16: one warp per group, use __shfl_down_sync over 16 lanes.

__global__ void fused_gn_lrelu_sum_g16_kernel(
    const float* __restrict__ input,
    const float* __restrict__ gn_weight,
    const float* __restrict__ gn_bias,
    float* __restrict__ output,
    int batch_size,
    int hidden_size,
    int num_groups,
    float eps,
    float negative_slope)
{
    // Each block handles one (batch_row, group) pair.
    // blockDim.x = 32, but group_size = 16 so lane 0..15 are active.
    int group_idx = blockIdx.x;  // global group index across all rows
    int row = group_idx / num_groups;
    int grp = group_idx % num_groups;
    int group_size = hidden_size / num_groups;  // == 16 for this kernel

    int lane = threadIdx.x;  // 0..31
    bool active = (lane < group_size);

    int base = row * hidden_size + grp * group_size;

    float val = 0.0f;
    if (active) {
        val = input[base + lane];
    }

    // Warp-reduce sum over first 16 lanes for mean
    float sum = val;
    // reduce over 16 lanes using shuffle
    sum += __shfl_down_sync(0x0000FFFF, sum, 8);
    sum += __shfl_down_sync(0x0000FFFF, sum, 4);
    sum += __shfl_down_sync(0x0000FFFF, sum, 2);
    sum += __shfl_down_sync(0x0000FFFF, sum, 1);
    float mean = __shfl_sync(0x0000FFFF, sum, 0) / (float)group_size;

    // Warp-reduce sum of squares for variance
    float diff = active ? (val - mean) : 0.0f;
    float sq = diff * diff;
    sq += __shfl_down_sync(0x0000FFFF, sq, 8);
    sq += __shfl_down_sync(0x0000FFFF, sq, 4);
    sq += __shfl_down_sync(0x0000FFFF, sq, 2);
    sq += __shfl_down_sync(0x0000FFFF, sq, 1);
    float var = __shfl_sync(0x0000FFFF, sq, 0) / (float)group_size;
    float inv_std = rsqrtf(var + eps);

    if (active) {
        int ch = grp * group_size + lane;
        float norm_val = (val - mean) * inv_std;
        float gamma = gn_weight[ch];
        float beta = gn_bias[ch];
        float out_val = norm_val * gamma + beta;
        // LeakyReLU
        out_val = (out_val >= 0.0f) ? out_val : out_val * negative_slope;
        // x + x == 2 * x
        output[base + lane] = out_val * 2.0f;
    }
}

// Generic kernel for arbitrary group_size, using shared memory reduction
__global__ void fused_gn_lrelu_sum_generic_kernel(
    const float* __restrict__ input,
    const float* __restrict__ gn_weight,
    const float* __restrict__ gn_bias,
    float* __restrict__ output,
    int batch_size,
    int hidden_size,
    int num_groups,
    int group_size,
    float eps,
    float negative_slope)
{
    extern __shared__ float smem[];
    // smem layout: [group_size] vals, [blockDim.x] for reduction
    float* partial = smem;  // blockDim.x floats

    int group_idx = blockIdx.x;
    int row = group_idx / num_groups;
    int grp = group_idx % num_groups;
    int base = row * hidden_size + grp * group_size;

    int tid = threadIdx.x;
    int nthreads = blockDim.x;

    // Each thread accumulates sum and sum-of-squares for its assigned elements
    float local_sum = 0.0f;
    float local_sq = 0.0f;
    for (int i = tid; i < group_size; i += nthreads) {
        float v = input[base + i];
        local_sum += v;
        local_sq += v * v;
    }

    // Block reduce
    partial[tid] = local_sum;
    __syncthreads();
    for (int s = nthreads / 2; s > 0; s >>= 1) {
        if (tid < s) partial[tid] += partial[tid + s];
        __syncthreads();
    }
    float mean = partial[0] / (float)group_size;
    __syncthreads();

    partial[tid] = local_sq;
    __syncthreads();
    for (int s = nthreads / 2; s > 0; s >>= 1) {
        if (tid < s) partial[tid] += partial[tid + s];
        __syncthreads();
    }
    float var = partial[0] / (float)group_size - mean * mean;
    float inv_std = rsqrtf(var + eps);
    __syncthreads();

    for (int i = tid; i < group_size; i += nthreads) {
        int ch = grp * group_size + i;
        float val = input[base + i];
        float norm_val = (val - mean) * inv_std;
        float out_val = norm_val * gn_weight[ch] + gn_bias[ch];
        out_val = (out_val >= 0.0f) ? out_val : out_val * negative_slope;
        output[base + i] = out_val * 2.0f;
    }
}

torch::Tensor fused_groupnorm_leakyrelu_sum_cuda(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    int64_t num_groups,
    double eps,
    double negative_slope)
{
    TORCH_CHECK(x.is_cuda() && x.is_contiguous() && x.scalar_type() == torch::kFloat32,
                "fused_groupnorm_leakyrelu_sum: expected CUDA float32 contiguous input");
    TORCH_CHECK(x.dim() == 2, "fused_groupnorm_leakyrelu_sum: expected 2D input");

    int batch_size = x.size(0);
    int hidden_size = x.size(1);
    int group_size = hidden_size / (int)num_groups;

    auto output = torch::empty_like(x);

    const float* x_ptr = x.data_ptr<float>();
    const float* w_ptr = weight.contiguous().data_ptr<float>();
    const float* b_ptr = bias.contiguous().data_ptr<float>();
    float* out_ptr = output.data_ptr<float>();

    int total_groups = batch_size * (int)num_groups;

    if (group_size == 16) {
        // Specialized: one warp per group (32 threads, 16 active)
        dim3 grid(total_groups);
        dim3 block(32);
        fused_gn_lrelu_sum_g16_kernel<<<grid, block>>>(
            x_ptr, w_ptr, b_ptr, out_ptr,
            batch_size, hidden_size, (int)num_groups,
            (float)eps, (float)negative_slope);
    } else {
        // Generic path
        int nthreads = std::min(group_size, 256);
        // Round up to next power of two for reduction
        int nt = 1;
        while (nt < nthreads) nt <<= 1;
        nthreads = nt;
        size_t smem_bytes = nthreads * sizeof(float);
        dim3 grid(total_groups);
        dim3 block(nthreads);
        fused_gn_lrelu_sum_generic_kernel<<<grid, block, smem_bytes>>>(
            x_ptr, w_ptr, b_ptr, out_ptr,
            batch_size, hidden_size, (int)num_groups, group_size,
            (float)eps, (float)negative_slope);
    }

    return output;
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    """
        A model that performs a matrix multiplication, group normalization, leaky ReLU activation, and element-wise sum.
        """
    def __init__(self, input_size, hidden_size, num_groups, eps=1e-5, negative_slope=0.01):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        self.fc = nn.Linear(input_size, hidden_size)
        self.gn = nn.GroupNorm(num_groups=num_groups, num_channels=hidden_size, eps=eps)
        self.leaky_relu = nn.LeakyReLU(negative_slope=negative_slope)
        # <<<END_IMPROVE>>>

    def forward(self, x):
        # <<<IMPROVE:forward_stmt_1>>>
        # Baseline fallback keeps the official PyTorch forward path.
        # After implementing CUDA_CPP_SRC / CUDA_CU_SRC, call _stark_get_extension().your_entrypoint(...).
        """
                Performs the forward pass of the model.

                Args:
                    x: Input tensor of shape (batch_size, input_size).

                Returns:
                    Output tensor of shape (batch_size, hidden_size).
                """
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_2>>>
        x = self.fc(x)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_3>>>
        if x.is_cuda and x.is_contiguous() and x.dtype == torch.float32 and x.dim() == 2:
            x = _stark_get_extension().fused_groupnorm_leakyrelu_sum(
            x, self.gn.weight, self.gn.bias,
            self.gn.num_groups, self.gn.eps,
            self.leaky_relu.negative_slope)
            return x
        else:
            x = self.gn(x)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_4>>>
        x = self.leaky_relu(x)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_5>>>
        x = x + x
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_6>>>
        return x
        # <<<END_IMPROVE>>>

