#include <cuda.h>
#include <cuda_runtime.h>

// Dual-half-warp specialized kernel for group_size == 16.
// Each 32-thread warp handles TWO consecutive groups.
// Lanes 0..15  -> group (block_group_idx * 2 + 0)
// Lanes 16..31 -> group (block_group_idx * 2 + 1)
// Shuffle masks: 0x0000FFFF for low half, 0xFFFF0000 for high half.
__global__ void fused_gn_lrelu_sum_g16_dual_kernel(
    const float* __restrict__ input,
    const float* __restrict__ gn_weight,
    const float* __restrict__ gn_bias,
    float* __restrict__ output,
    int batch_size,
    int hidden_size,
    int num_groups,
    int total_groups,
    float eps,
    float negative_slope)
{
    // blockIdx.x indexes pairs of groups
    int pair_idx = blockIdx.x;
    int lane = threadIdx.x;  // 0..31

    // Which half-warp am I in?
    int half = lane >> 4;          // 0 for lanes 0-15, 1 for lanes 16-31
    int local_lane = lane & 15;    // 0..15 within the half-warp

    int group_idx = pair_idx * 2 + half;  // global group index

    // Shuffle mask for this half-warp
    unsigned int mask = (half == 0) ? 0x0000FFFFu : 0xFFFF0000u;

    float val = 0.0f;
    int base = 0;
    bool valid = (group_idx < total_groups);

    if (valid) {
        int row = group_idx / num_groups;
        int grp = group_idx % num_groups;
        base = row * hidden_size + grp * 16;
        val = input[base + local_lane];
    }

    // Reduce sum over 16 lanes in this half-warp
    float sum = val;
    sum += __shfl_down_sync(mask, sum, 8);
    sum += __shfl_down_sync(mask, sum, 4);
    sum += __shfl_down_sync(mask, sum, 2);
    sum += __shfl_down_sync(mask, sum, 1);
    // Broadcast mean to all lanes in the half-warp
    int root_lane = half * 16;  // lane 0 or lane 16
    float mean = __shfl_sync(mask, sum, root_lane) / 16.0f;

    // Reduce sum-of-squares
    float diff = valid ? (val - mean) : 0.0f;
    float sq = diff * diff;
    sq += __shfl_down_sync(mask, sq, 8);
    sq += __shfl_down_sync(mask, sq, 4);
    sq += __shfl_down_sync(mask, sq, 2);
    sq += __shfl_down_sync(mask, sq, 1);
    float var = __shfl_sync(mask, sq, root_lane) / 16.0f;
    float inv_std = rsqrtf(var + eps);

    if (valid) {
        int row = group_idx / num_groups;
        int grp = group_idx % num_groups;
        int ch = grp * 16 + local_lane;
        float norm_val = (val - mean) * inv_std;
        float out_val = norm_val * gn_weight[ch] + gn_bias[ch];
        out_val = (out_val >= 0.0f) ? out_val : out_val * negative_slope;
        output[base + local_lane] = out_val * 2.0f;
    }
}

